// Application-first overview. These are saved records, not claims of live workers.
function submittedRecord(j){return ['Applied','Interviewing','Offer','Rejected','Withdrawn'].includes(j.stage)||(j.history||[]).some(h=>h.stage==='Applied'&&h.evidence)}
function applicationOrder(j){if(submittedRecord(j))return 9;if(j.council?.startsWith('Approved'))return j.stage==='Preparing'?0:1;if(j.council_queue==='reviewing')return 2;if(j.scout_status==='Ready for council')return 3;if(j.scout_status==='Excluded')return 8;return 4}
function nextApplications(){return state.opportunities.filter(j=>applicationOrder(j)<8).sort((a,b)=>applicationOrder(a)-applicationOrder(b)||(a.deadline||'9999').localeCompare(b.deadline||'9999')||Object.values(a.research?.gates||{}).filter(g=>g.status==='unknown').length-Object.values(b.research?.gates||{}).filter(g=>g.status==='unknown').length)}
function readyDrafts(){const active=new Set(state.opportunities.filter(j=>!submittedRecord(j)&&j.council?.startsWith('Approved')).map(j=>j.id));return new Set(state.approvals.filter(a=>a.kind==='application'&&a.ready&&['pending','approved','ready_auto_submit'].includes(a.status)&&active.has(a.opportunity_id)).map(a=>a.opportunity_id)).size}
stats=function(){const preparing=state.opportunities.filter(j=>!submittedRecord(j)&&j.stage==='Preparing').length;const pending=state.approvals.filter(a=>a.status==='pending'&&a.kind==='question').length;return `<div class="stats"><div class="stat accent"><div class="stat-top">SUBMITTED TODAY <span>↗</span></div><strong>${dailySubmitted()} / 5</strong><small>Employer-confirmed · Eastern time</small></div><div class="stat"><div class="stat-top">COMPLETED DRAFTS <span>◇</span></div><strong>${readyDrafts()}</strong><small>Ready for automatic submission</small></div><div class="stat"><div class="stat-top">IN PREPARATION <span>✎</span></div><strong>${preparing}</strong><small>Saved forms and materials</small></div><div class="stat"><div class="stat-top">YOUR NEXT ACTIONS <span>◉</span></div><strong>${pending}</strong><small>Questions and corrections</small></div></div>`};
function applicationFocus(){const jobs=nextApplications().slice(0,3);return `<section class="application-focus" aria-label="Application priorities"><div class="section-head"><h2>Finish the next application</h2><span class="badge approved">Application-first</span></div><p class="caption">Work through saved leads first. Research only the missing fact that moves an application forward.</p><div class="queue">${jobs.map(j=>`<article class="queue-card"><div class="eyebrow">${j.council?.startsWith('Approved')?'APPROVED · NEXT APPLICATION':'SAVED LEAD · NEXT STEP'}</div><h3>${esc(j.company)}</h3><p>${esc(j.title)}</p><p>${esc(j.next_action||'Review the saved evidence and identify the next step.')}</p><button class="secondary" data-job="${esc(j.id)}">Open application record →</button></article>`).join('')||'<p>No unsubmitted candidates in the current queue.</p>'}</div></section>`}
workers[0].description='Resolve a specific blocker in a saved lead. Discover new internships only when the existing backlog cannot supply the next application.';
workers[0].details='Application-first: approved forms and existing-lead reviews take priority. No routine daily sweep while viable saved leads can advance. Five independent reviewers and the challenge round remain required. Complete eligible applications may be submitted automatically under standing authorization.';
